import 'package:flutter/material.dart';
import 'package:device_preview/device_preview.dart';

// 특정 기기만 표시
void main() {
  runApp(
    DevicePreview(
      enabled: true,
      // 표시할 기기 목록 제한
      devices: [
        ...Devices.ios.all,      // 모든 iOS 기기
        ...Devices.android.all,  // 모든 Android 기기
        Devices.ios.iPhone13,    // 특정 기기
        Devices.ios.iPhone13ProMax,
        Devices.ios.iPadPro11Inches,
        Devices.android.samsungGalaxyS20,
      ],
      // 기본 선택 기기
      defaultDevice: Devices.ios.iPhone13,
      builder: (context) => const MyApp(),
    ),
  );
}

// 사용 가능한 기기 프리셋 예시
// Devices.ios: iPhone SE, iPhone 13 시리즈, iPad 시리즈
// Devices.android: Pixel, Samsung Galaxy 시리즈, 소형/중형/대형 폰
// Devices.macOS, Devices.windows, Devices.linux: 데스크톱
// Devices.freeform: 사용자 정의 크기

import 'package:flutter/material.dart';
import 'package:device_preview/device_preview.dart';
import 'package:shared_preferences/shared_preferences.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();

  runApp(
    DevicePreview(
      enabled: true,
      // 설정을 SharedPreferences에 저장
      storage: DevicePreviewStorage.preferences(),
      builder: (context) => const MyApp(),
    ),
  );
}

// 또는 메모리에만 저장 (앱 재시작 시 초기화)
void mainWithMemoryStorage() {
  runApp(
    DevicePreview(
      enabled: true,
      storage: DevicePreviewStorage.none(),
      builder: (context) => const MyApp(),
    ),
  );
}

import 'package:flutter/material.dart';
import 'package:device_preview/device_preview.dart';

void main() {
  runApp(
    DevicePreview(
      enabled: true,
      tools: const [
        // 사용할 도구 선택
        ...DevicePreview.defaultTools,
      ],
      builder: (context) => const MyApp(),
    ),
  );
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      useInheritedMediaQuery: true,
      locale: DevicePreview.locale(context),
      builder: DevicePreview.appBuilder,
      theme: ThemeData.light(),
      darkTheme: ThemeData.dark(),
      home: const ResponsiveHomeScreen(),
    );
  }
}

class ResponsiveHomeScreen extends StatelessWidget {
  const ResponsiveHomeScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('반응형 테스트')),
      body: LayoutBuilder(
        builder: (context, constraints) {
          // 화면 너비에 따른 레이아웃 분기
          if (constraints.maxWidth > 1200) {
            return const _DesktopLayout();
          } else if (constraints.maxWidth > 600) {
            return const _TabletLayout();
          } else {
            return const _MobileLayout();
          }
        },
      ),
    );
  }
}

class _MobileLayout extends StatelessWidget {
  const _MobileLayout();

  @override
  Widget build(BuildContext context) {
    return ListView(
      padding: const EdgeInsets.all(16),
      children: [
        _buildInfoCard(context, 'Mobile Layout'),
        const SizedBox(height: 16),
        ...List.generate(
          5,
          (index) => _buildListItem(context, index),
        ),
      ],
    );
  }
}

class _TabletLayout extends StatelessWidget {
  const _TabletLayout();

  @override
  Widget build(BuildContext context) {
    return Row(
      children: [
        NavigationRail(
          selectedIndex: 0,
          destinations: const [
            NavigationRailDestination(
              icon: Icon(Icons.home),
              label: Text('홈'),
            ),
            NavigationRailDestination(
              icon: Icon(Icons.settings),
              label: Text('설정'),
            ),
          ],
        ),
        Expanded(
          child: GridView.builder(
            padding: const EdgeInsets.all(16),
            gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 2,
              mainAxisSpacing: 16,
              crossAxisSpacing: 16,
            ),
            itemCount: 6,
            itemBuilder: (context, index) => _buildGridItem(context, index),
          ),
        ),
      ],
    );
  }
}

class _DesktopLayout extends StatelessWidget {
  const _DesktopLayout();

  @override
  Widget build(BuildContext context) {
    return Row(
      children: [
        SizedBox(
          width: 250,
          child: ListView(
            padding: const EdgeInsets.all(16),
            children: [
              _buildInfoCard(context, 'Desktop Layout'),
              const SizedBox(height: 16),
              ...List.generate(
                5,
                (index) => ListTile(title: Text('메뉴 $index')),
              ),
            ],
          ),
        ),
        const VerticalDivider(),
        Expanded(
          child: GridView.builder(
            padding: const EdgeInsets.all(16),
            gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 3,
              mainAxisSpacing: 16,
              crossAxisSpacing: 16,
            ),
            itemCount: 9,
            itemBuilder: (context, index) => _buildGridItem(context, index),
          ),
        ),
      ],
    );
  }
}

Widget _buildInfoCard(BuildContext context, String title) {
  final size = MediaQuery.of(context).size;
  return Card(
    child: Padding(
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(title, style: const TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),
          const SizedBox(height: 8),
          Text('화면 크기: ${size.width.toInt()} x ${size.height.toInt()}'),
          Text('기기 픽셀 비율: ${MediaQuery.of(context).devicePixelRatio}'),
        ],
      ),
    ),
  );
}

Widget _buildListItem(BuildContext context, int index) {
  return Card(
    child: ListTile(
      leading: CircleAvatar(child: Text('$index')),
      title: Text('아이템 $index'),
      subtitle: const Text('설명 텍스트'),
    ),
  );
}

Widget _buildGridItem(BuildContext context, int index) {
  return Card(
    child: Center(
      child: Text('그리드 $index', style: const TextStyle(fontSize: 18)),
    ),
  );
}
